"""Shared helpers for the desktop and terminal dashboards."""

import shlex
from datetime import UTC, datetime, timedelta
from importlib.resources import files

from siemstress.event import ACKNOWLEDGED, FAILURE, OPEN, RESOLVED, SUCCESS, Alert, Level

# Icon and logo, generated by tools/make_art.py.
ASSETS = files("siemstress") / "assets"
ICON_SIZES = (16, 22, 24, 32, 48, 64, 128, 256)

# One palette, one meaning per color, in every view:
#   red = critical or failed, orange = high, amber = medium / needs a look,
#   blue = low / informational, green = fine or resolved, gray = handled or background.
# Mid-tone values stay readable on both light and dark themes.
RED = "#d93f3f"
ORANGE = "#e8663d"
AMBER = "#e0a526"
BLUE = "#5b8def"
GREEN = "#3aa55d"
GRAY = "#8a93a3"

LEVEL_COLORS = {Level.LOW: BLUE, Level.MEDIUM: AMBER, Level.HIGH: ORANGE, Level.CRITICAL: RED}
OUTCOME_COLORS = {SUCCESS: GREEN, FAILURE: RED}
STATUS_MARKERS = {OPEN: "●", ACKNOWLEDGED: "◐", RESOLVED: "✓"}
HOST_STATE_COLORS = {"ok": GREEN, "quiet": AMBER, "silent": RED}
WINDOWS = {
    "1h": timedelta(hours=1),
    "24h": timedelta(hours=24),
    "7d": timedelta(days=7),
    "30d": timedelta(days=30),
}
# A host that has sent nothing for this long is quiet, then silent (likely down or cut off).
QUIET_AFTER = timedelta(hours=1)
SILENT_AFTER = timedelta(hours=24)

_QUERY_KEYS = {
    "action": "action",
    "outcome": "outcome",
    "user": "user",
    "ip": "src_ip",
    "host": "host",
    "app": "app",
}


def status_color(alert: Alert) -> str:
    """Open alerts wear their level's color; handled ones fade to gray, resolved turn green."""
    return {ACKNOWLEDGED: GRAY, RESOLVED: GREEN}.get(alert.status, LEVEL_COLORS[alert.level])


def severity_color(severity: int | None) -> str | None:
    """Color for a raw syslog severity: errors red, warnings amber, debug gray."""
    if severity is None:
        return None
    if severity <= 3:
        return RED
    return {4: AMBER, 7: GRAY}.get(severity)


def host_state(last_seen: datetime, now: datetime | None = None) -> str:
    silence = (now or datetime.now(UTC)) - last_seen
    if silence > SILENT_AFTER:
        return "silent"
    return "quiet" if silence > QUIET_AFTER else "ok"


def users_text(users: tuple[str, ...], shown: int = 3) -> str:
    more = f" +{len(users) - shown}" if len(users) > shown else ""
    return ", ".join(users[:shown]) + more


def ago(ts: datetime, now: datetime | None = None) -> str:
    seconds = int(((now or datetime.now(UTC)) - ts).total_seconds())
    if seconds < 60:
        return "just now"
    for unit, size in (("d", 86400), ("h", 3600), ("m", 60)):
        if seconds >= size:
            return f"{seconds // size}{unit} ago"
    return "just now"


def local_time(ts: datetime) -> str:
    return f"{ts.astimezone():%Y-%m-%d %H:%M:%S}"


def short_host(host: str | None) -> str:
    return (host or "?").split(".")[0]


def describe_bucket(bucket: timedelta) -> str:
    minutes = round(bucket.total_seconds() / 60)
    if minutes % 1440 == 0:
        return "day" if minutes == 1440 else f"{minutes // 1440} days"
    if minutes % 60 == 0:
        return "hour" if minutes == 60 else f"{minutes // 60} hours"
    return f"{minutes} min"


def parse_query(text: str) -> dict[str, str]:
    """Turn `action:ssh ip:10.0.0.9 failed password` into Store.search() filters.

    Unrecognized `key:value` terms and bare words are searched as message text.
    """
    try:
        terms = shlex.split(text)
    except ValueError:  # unbalanced quote
        terms = text.split()
    filters: dict[str, str] = {}
    words = []
    for term in terms:
        key, sep, value = term.partition(":")
        if sep and value and key in _QUERY_KEYS:
            filters[_QUERY_KEYS[key]] = value
        else:
            words.append(term)
    if words:
        filters["text"] = " ".join(words)
    return filters
